#!/usr/bin/env node
/**
 * بوّابةُ ميزانيّةِ الوثائق المحقونة — تجعل النموَّ الصامتَ مرئيّاً.
 * ─────────────────────────────────────────────────────────────────
 * لماذا وُجدت (مقيسٌ 2026-09-20 من تاريخ git، لا مُقدَّر):
 *
 *   2026-09-11  ⇒ 69,257 بايت
 *   2026-09-12  ⇒ 37,921   🟢 تقليمٌ كبير (−31,336) بنقل التفصيل إلى `_docs/`
 *   2026-09-20  ⇒ 57,119   🔴 +19,198 في ثمانية أيام (~+2,400/يوم)
 *
 * ⇒ **التقليمُ نُفِّذ فعلاً ثمّ أُعيد بناءُ ثلثيه في ثمانية أيام.** والعلّةُ ليست
 * الحجمَ بل أن النموَّ **غيرُ مرئيّ**: كلُّ جلسةٍ تضيف ~1,500 بايتاً **مبرَّرةً
 * بحقّ**، ولا أحدَ يرى المجموع. ⇒ تقليمٌ ثانٍ بلا بوّابةٍ **يمحو نفسَه خلال أسبوعين**.
 *
 * 🔴 ولماذا يهمّ الحجمُ أصلاً — وهو ليس تفضيلاً جمالياً:
 * `CLAUDE.md` يُحقَن في **كلّ** جلسةٍ على هذا المستودع، و**يُعاد إرسالُه مع كلّ
 * نداءٍ إلى النموذج** لا مرّةً واحدة. فكلُّ بايتٍ هنا يُدفع ثمنُه مئاتِ المرّات
 * في اليوم: بطءُ أوّلِ حرف · وكلفةٌ أعلى · وحساسيّةٌ أكبر للإجهاد.
 *
 * 🎯 وما تفعله هذه البوّابةُ بالضبط: **لا تمنع الكتابة.** تمنع أن تمرَّ الزيادةُ
 * **بلا قرار**. من تجاوز السقفَ فأمامه بابان صريحان — ينقل تفصيلاً إلى `_docs/`
 * ويُبقي الحكمَ هنا (نمطُ «مؤشّرٌ لا سرد» المطبَّقُ سلفاً في أربعة أقسام)، أو
 * **يرفع السقفَ عامداً ويكتب لماذا**. وكلاهما مقبول؛ والمرفوضُ وحدَه النموُّ الصامت.
 *
 * ⚠️ وحدُّ هذه البوّابة يُقال بدل الإيهام: هي تقيس **البايتات لا التوكنات**.
 * والعربيّةُ في UTF-8 بايتان للمحرف تقريباً، ونسبةُ التوكن تختلف. ⇒ الرقمُ
 * **وكيلٌ مستقرٌّ للاتّجاه**، لا قياسٌ للتوكن. والقياسُ الحاكمُ للتوكن `/context`.
 */

'use strict';

var fs = require('fs');
var path = require('path');

var ROOT = path.join(__dirname, '..', '..');

/**
 * 🔴 السقفُ يُرفَع عامداً مع سببٍ مكتوب، ولا يُرفَع لتمرير بوّابةٍ حمراء.
 * ضُبط 2026-09-20 عند 58,000 — أي **+881 فوق المقيس (57,119)**، لا رقماً مستديراً
 * بعيداً. والضيقُ مقصود: الفسحةُ الواسعةُ تجعل البوّابةَ تحمرّ بعد أسبوعين من النموّ
 * **فتصير أثراً لا إنذاراً**.
 */
var BUDGET = [
  {
    file: 'CLAUDE.md',
    maxBytes: 58000,
    why: 'يُحقَن في كلّ جلسةٍ ويُعاد إرسالُه مع كلّ نداء'
  }
];

/** يقارن حجماً بسقف. مفصولةٌ عن القراءة عمداً كي تُختبَر وحدَها. */
function verdict(bytes, maxBytes) {
  return bytes > maxBytes ? 'over' : 'ok';
}

/**
 * 🔴 الضابطُ المعاكس — يسبق القياسَ الحقيقيّ ولا يليه.
 * فحصٌ لا يُثبت أنه **يستطيع** أن يحمرّ ليس فحصاً: لو انقلب `>` إلى `<` لمرّ كلُّ
 * شيءٍ أخضرَ أبداً، **والمخرَجُ يبدو سليماً تماماً**. وهذه هي فئةُ العطل المهيمنة
 * على هذا الجهاز: لا خطأ، لا صفر، لا سطرٌ أحمر — فقط بوّابةٌ كفّت عن القياس.
 */
function selfTest() {
  var cases = [
    { bytes: 100, max: 50, want: 'over', label: 'فوق السقف ⇒ يحمرّ' },
    { bytes: 10, max: 50, want: 'ok', label: 'تحت السقف ⇒ يخضرّ' },
    { bytes: 50, max: 50, want: 'ok', label: 'عند السقف بالضبط ⇒ يخضرّ (الحدُّ مشمول)' }
  ];
  var bad = cases.filter(function (c) { return verdict(c.bytes, c.max) !== c.want; });
  if (bad.length) {
    console.error('🔴 الضابطُ المعاكس سقط — البوّابةُ لا تقيس:');
    bad.forEach(function (c) {
      console.error('   ' + c.label + ' — توقّعتُ ' + c.want + ' وجاء ' + verdict(c.bytes, c.max));
    });
    process.exit(2);
  }
  console.log('✅ الضابطُ المعاكس: البوّابةُ تحمرّ فوق السقف وتخضرّ تحته (٣ حالات)');
}

function main() {
  selfTest();

  var failed = 0;
  console.log('');
  console.log('ميزانيّةُ الوثائق المحقونة:');

  BUDGET.forEach(function (b) {
    var p = path.join(ROOT, b.file);
    if (!fs.existsSync(p)) {
      // 🔴 غيابُ الملفّ خروجٌ أحمرُ لا تخطٍّ صامت: بوّابةٌ تقيس ملفّاً غيرَ موجودٍ
      //    تُعلن النجاحَ أبداً، وهي أسوأ من غيابها.
      console.error('🔴 ' + b.file + ' مفقود — البوّابةُ تقيس فراغاً');
      failed++;
      return;
    }
    var bytes = fs.statSync(p).size;
    var v = verdict(bytes, b.maxBytes);
    var pct = Math.round((bytes / b.maxBytes) * 100);
    var left = b.maxBytes - bytes;
    console.log(
      '  ' + (v === 'ok' ? '✅' : '🔴') + ' ' + b.file +
      '  ' + bytes + ' / ' + b.maxBytes + ' بايت  (' + pct + '%' +
      (v === 'ok' ? ' · المتبقّي ' + left : ' · التجاوز ' + (-left)) + ')'
    );
    if (v === 'over') {
      failed++;
      console.error('');
      console.error('::error::' + b.file + ' تجاوز ميزانيّتَه بـ' + (-left) + ' بايتاً.');
      console.error('السبب الذي وُضعت له الميزانيّة: ' + b.why + '.');
      console.error('');
      console.error('ولك بابان صريحان — كلاهما مقبول، والمرفوضُ النموُّ الصامتُ وحدَه:');
      console.error('  ① انقل التفصيلَ إلى `_docs/` **بحرفه** وأبقِ هنا الحكمَ الذي');
      console.error('     يُخالَف عند نقطة القرار (نمطُ «مؤشّرٌ لا سرد» — مطبَّقٌ سلفاً');
      console.error('     في أربعة أقسام، وأنقذ 31,336 بايتاً في 2026-09-12).');
      console.error('  ② ارفع `maxBytes` في `.github/scripts/check-doc-budget.js`');
      console.error('     **واكتب في نفس الدفعة لماذا** — فيبقى القرارُ مقروءاً لمن بعدك.');
      console.error('');
      console.error('🔴 ولا تحذف حكماً لتقليل الحجم: هذا الملفُّ يمنع كسرَ نشرٍ حيّ.');
      console.error('   والهدفُ نقلُ السرد لا إسقاطُ القيود.');
    }
  });

  console.log('');
  console.log('RESULT: ' + (failed ? '🔴 ' + failed + ' تجاوزاً' : '✅ داخل الميزانيّة'));
  process.exit(failed ? 1 : 0);
}

main();
